package fr.godox.figlekt.core

/**
 * A FIGlet font.
 *
 * Fonts are declared by the `fr.godox.figlekt.fonts` Gradle plugin, or by pasting the property
 * generated by the Kotlin/Wasm web page straight into the sources: dropping a `standard.flf` file
 * into `src/<sourceSet>/resources/flf` of a project turns into a `Font.standard` property, the font
 * content being compiled into the artifact as plain Kotlin source, so that everything stays
 * synchronous and usable from common code.
 */
class FigletFont(
    val name: String,
    val filename: String,
    private val supplier: () -> String,
) {

    /**
     * Returns the raw FIGlet font file content.
     */
    fun data(): String = supplier()

    override fun toString(): String = name
}

/**
 * The object the generated font properties are attached to.
 *
 * ```kotlin
 * Figlekt.figletify("Hello, World!", Font.standard)
 * ```
 */
object Font